from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["Táctica y puntos"])


@router.get("/tablet/tactics-points", response_class=HTMLResponse, include_in_schema=False)
async def tactics_points_page():
    """Voice-enabled point capture; each transcript is reviewed before persistence."""
    return HTMLResponse(content=r'''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Táctica y puntos | SquashAnalytics Pro</title>
<style>
:root{color-scheme:dark;--bg:#101820;--panel:#192630;--line:#314653;--text:#edf5f7;--muted:#a9bdc6;--accent:#7be0ad;--warn:#ffd37a}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,sans-serif}header{padding:16px clamp(16px,4vw,48px);border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}a{color:var(--accent);text-decoration:none}main{max-width:980px;margin:auto;padding:24px clamp(14px,4vw,32px)}section{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:20px;margin-top:16px}h1{margin:0}h2{margin-top:0;font-size:1.2rem}.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px}label{display:block;margin:10px 0 5px;font-weight:650}input,select{width:100%;min-height:46px;padding:9px 11px;background:#101a21;color:var(--text);border:1px solid #49606c;border-radius:8px;font:inherit}button{min-height:48px;padding:10px 16px;border:0;border-radius:8px;background:var(--accent);color:#10231a;font:inherit;font-weight:700;cursor:pointer}.secondary{background:#1b3442;color:var(--text);border:1px solid var(--line)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.actions button{flex:1}.status,.preview{margin-top:12px;padding:13px;border:1px solid var(--line);border-radius:9px;background:#102128}.preview{background:#122c21;border-color:#38644d}[hidden]{display:none!important}
</style></head><body>
<header><strong>SquashAnalytics Pro · Táctica y puntos</strong><nav><a href="/tablet/clinical-profile">Ficha clínica</a> · <a href="/docs">API</a></nav></header>
<main><h1>Táctica y puntos</h1><p class="muted">Dicta la jugada. La app muestra la transcripción y los campos interpretados; nada se guarda hasta que confirmes.</p>
<section><h2>Datos del punto</h2><div class="grid"><div><label for="match">ID del partido</label><input id="match" type="number" min="1" required></div><div><label for="player">ID del jugador</label><input id="player" type="number" min="1" required></div><div><label for="set">Set</label><input id="set" type="number" min="1" value="1" required></div><div><label for="score">Puntuación</label><input id="score" maxlength="20" value="0-0" required></div></div></section>
<section><h2>Comando por voz</h2><p class="muted">Ejemplos: “derecho ataque winner”, “drop revés defensa let”, “llegada a la T”. El navegador puede requerir conexión segura (HTTPS) y permiso de micrófono.</p><div class="actions"><button id="listen" type="button">🎙️ Dictar jugada</button><button id="stop" class="secondary" type="button">Detener</button></div><div id="transcript" class="status" aria-live="polite">Esperando comando.</div><div class="actions"><button id="apply" class="secondary" type="button">Interpretar y mostrar para revisión</button></div></section>
<section><h2>Confirmación de la jugada</h2><div class="grid"><div><label for="stroke">Tipo de golpe</label><select id="stroke"><option value="derecho">Derecho</option><option value="reves">Revés</option><option value="boast">Boast</option><option value="volea">Volea</option><option value="drop_derecho">Drop derecho</option><option value="drop_reves">Drop revés</option><option value="lob_derecho">Lob derecho</option><option value="lob_reves">Lob revés</option></select></div><div><label for="tactic">Intención</label><select id="tactic"><option value="ataque">Ataque</option><option value="defensa">Defensa</option></select></div><div><label for="outcome">Resultado</label><select id="outcome"><option value="ganador">Killer shot / winner</option><option value="error_no_forzado">Error no forzado</option><option value="let">Let</option><option value="stroke">Stroke</option></select></div><div><label for="t-arrival">¿Volvió el jugador a la T en esta jugada?</label><select id="t-arrival"><option value="false">No</option><option value="true">Sí, contar llegada</option></select></div></div><div id="preview" class="preview" aria-live="polite">Aún no se ha guardado ninguna jugada.</div><div class="actions"><button id="save" type="button">Confirmar y guardar</button><button id="clear" class="secondary" type="button">Limpiar / siguiente</button></div><div id="status" class="status" aria-live="polite"></div></section>
<section><h2>Estadística guardada</h2><div class="actions"><button id="refresh" class="secondary" type="button">Actualizar eventos y llegadas a la T</button></div><div id="stats" class="status" aria-live="polite">Ingresa el partido para consultar la estadística.</div></section>
</main>
<script>
const $=s=>document.querySelector(s), transcript=$('#transcript'), preview=$('#preview'), statusBox=$('#status'), stats=$('#stats');
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;let recognition=null,recognized='';
function norm(s){return s.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim()}
$('#listen').addEventListener('click',()=>{if(!SpeechRecognition){transcript.textContent='Este navegador no soporta reconocimiento de voz. Usa los controles manuales.';return}if(!recognition){recognition=new SpeechRecognition();recognition.lang='es-ES';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onresult=e=>{recognized=e.results[0][0].transcript;transcript.textContent=`Reconocido: “${recognized}”. Pulsa interpretar y revisa los campos.`};recognition.onerror=e=>{transcript.textContent=`No se reconoció el comando (${e.error}). Intenta de nuevo o usa controles manuales.`};recognition.onend=()=>$('#listen').disabled=false}recognized='';transcript.textContent='Escuchando…';$('#listen').disabled=true;try{recognition.start()}catch(e){$('#listen').disabled=false;transcript.textContent='El micrófono ya está activo. Deténlo e inténtalo otra vez.'}});
$('#stop').addEventListener('click',()=>{if(recognition)recognition.stop();$('#listen').disabled=false});
$('#apply').addEventListener('click',()=>{if(!recognized){transcript.textContent='Primero dicta un comando.';return}const t=norm(recognized),found=[];const hit=(phrase)=>t.includes(phrase);
const shots=[['drop derecho','drop_derecho'],['drop reves','drop_reves'],['lob derecho','lob_derecho'],['lob reves','lob_reves'],['derecho','derecho'],['derecha','derecho'],['reves','reves'],['boast','boast'],['volea','volea']];for(const [phrase,value] of shots){if(hit(phrase)){$('#stroke').value=value;found.push('golpe');break}}
if(hit('defensa')){$('#tactic').value='defensa';found.push('intención')}else if(hit('ataque')){$('#tactic').value='ataque';found.push('intención')}
if(hit('killer shot')||hit('winner')||hit('ganador')){$('#outcome').value='ganador';found.push('resultado')}else if(hit('error no forzado')||hit('error')){$('#outcome').value='error_no_forzado';found.push('resultado')}else if(hit('stroke')){$('#outcome').value='stroke';found.push('resultado')}else if(hit('let')){$('#outcome').value='let';found.push('resultado')}
if(hit('llegada a la t')||hit('llegue a la t')||hit('volvio a la t')||hit('vuelve a la t')||t==='t'){$('#t-arrival').value='true';found.push('llegada a la T')}
preview.textContent=`Transcripción: “${recognized}”. Interpretado: ${found.length?found.join(', '):'no se detectaron campos'}. Verifica o corrige los selectores antes de confirmar.`});
$('#save').addEventListener('click',async()=>{const partido_id=Number($('#match').value),jugador_id=Number($('#player').value),set_numero=Number($('#set').value);if(!partido_id||!jugador_id||!set_numero){statusBox.textContent='Completa partido, jugador y set.';return}const payload={partido_id,jugador_id,set_numero,puntuacion_actual:$('#score').value.trim(),tipo_resultado:$('#outcome').value,tipo_golpe:$('#stroke').value,tipo_tactica:$('#tactic').value,resultado_tactica:['ganador','stroke'].includes($('#outcome').value)?'acierto':'error',llegada_t:$('#t-arrival').value==='true'};if(!payload.puntuacion_actual){statusBox.textContent='Ingresa la puntuación.';return}if(!confirm(`¿Confirmas guardar esta jugada?\nGolpe: ${$('#stroke').selectedOptions[0].text}\nIntención: ${$('#tactic').value}\nResultado: ${$('#outcome').selectedOptions[0].text}\nVolvió a la T: ${payload.llegada_t?'sí':'no'}`))return;try{const r=await fetch('/events/point',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw Error(d.detail||'Error guardando');statusBox.textContent=`Evento guardado (#${d.id}). ${payload.llegada_t?'Llegada a la T contabilizada.':''}`;await refreshStats()}catch(e){statusBox.textContent=`No se pudo guardar: ${e.message}`}});
async function refreshStats(){const id=Number($('#match').value),player=Number($('#player').value);if(!id){stats.textContent='Ingresa el ID del partido.';return}try{const [eventsRes,tRes]=await Promise.all([fetch(`/events/matches/${id}/points?jugador_id=${player||''}`),fetch(`/events/matches/${id}/t-arrivals?jugador_id=${player||''}`)]);const ev=await eventsRes.json(),t=await tRes.json();if(!eventsRes.ok||!tRes.ok)throw Error(ev.detail||t.detail||'Error consultando');stats.textContent=`Eventos registrados: ${ev.eventos.length}. Llegadas a la T: ${t.llegadas_a_la_t}.`; }catch(e){stats.textContent=`No se pudo actualizar: ${e.message}`}}
$('#refresh').addEventListener('click',refreshStats);
$('#clear').addEventListener('click',()=>{recognized='';transcript.textContent='Esperando comando.';preview.textContent='Aún no se ha guardado ninguna jugada.';statusBox.textContent='';$('#stroke').value='derecho';$('#tactic').value='ataque';$('#outcome').value='ganador';$('#t-arrival').value='false'});
</script></body></html>''')
